namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string CourseCode { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Student Name is required.")]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    public string StudentId { get; set; } = string.Empty;

    public int CourseId { get; set; }

    public DateTime SubmittedAt { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollments = new();

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Description = "Exploration of numbers, structures, and patterns." },
            new() { Id = 3, Name = "English", Description = "Literature, writing, and language studies." },
            new() { Id = 4, Name = "Physics", Description = "Understanding the fundamental laws of the universe." }
        };

        _courses = new List<Course>
        {
            // Computer Science
            new() { Id = 1, DepartmentId = 1, CourseCode = "CS 101", Title = "Introduction to Computer Science", Description = "An introductory course covering the fundamentals of programming, data structures, and algorithmic thinking using Python.", Credits = 3, Schedule = "MWF 10:00-10:50", InstructorName = "Dr. Alice Chen", InstructorBio = "Dr. Chen holds a Ph.D. in Computer Science from MIT and has over 15 years of teaching experience in introductory programming.", IsFeatured = true },
            new() { Id = 2, DepartmentId = 1, CourseCode = "CS 201", Title = "Data Structures and Algorithms", Description = "In-depth study of fundamental data structures including trees, graphs, hash tables, and algorithm design techniques.", Credits = 4, Schedule = "TTh 9:00-10:20", InstructorName = "Dr. Alice Chen", InstructorBio = "Dr. Chen holds a Ph.D. in Computer Science from MIT and has over 15 years of teaching experience in introductory programming.", IsFeatured = false },
            new() { Id = 3, DepartmentId = 1, CourseCode = "CS 330", Title = "Database Systems", Description = "Relational database design, SQL, normalization, indexing, and transaction management.", Credits = 3, Schedule = "MWF 1:00-1:50", InstructorName = "Prof. Robert Kim", InstructorBio = "Prof. Kim spent a decade as a database architect at Oracle before joining academia. He specializes in distributed database systems.", IsFeatured = true },
            new() { Id = 4, DepartmentId = 1, CourseCode = "CS 450", Title = "Artificial Intelligence", Description = "Foundations of AI including search, knowledge representation, machine learning, and neural networks.", Credits = 3, Schedule = "TTh 2:00-3:20", InstructorName = "Dr. Maria Lopez", InstructorBio = "Dr. Lopez is an AI researcher with publications in NeurIPS and ICML. Her work focuses on natural language processing.", IsFeatured = false },

            // Mathematics
            new() { Id = 5, DepartmentId = 2, CourseCode = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions with applications to science and engineering.", Credits = 4, Schedule = "MWF 9:00-9:50", InstructorName = "Dr. James Wright", InstructorBio = "Dr. Wright is an award-winning mathematics educator with a passion for making calculus accessible to all students.", IsFeatured = true },
            new() { Id = 6, DepartmentId = 2, CourseCode = "MATH 201", Title = "Linear Algebra", Description = "Vector spaces, matrices, determinants, eigenvalues, and linear transformations.", Credits = 3, Schedule = "TTh 11:00-12:20", InstructorName = "Dr. Sarah Patel", InstructorBio = "Dr. Patel's research focuses on numerical linear algebra and its applications in data science.", IsFeatured = false },
            new() { Id = 7, DepartmentId = 2, CourseCode = "MATH 301", Title = "Probability and Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "MWF 11:00-11:50", InstructorName = "Dr. Sarah Patel", InstructorBio = "Dr. Patel's research focuses on numerical linear algebra and its applications in data science.", IsFeatured = false },

            // English
            new() { Id = 8, DepartmentId = 3, CourseCode = "ENG 101", Title = "English Composition", Description = "Fundamentals of academic writing, critical reading, thesis development, and research paper composition.", Credits = 3, Schedule = "MWF 10:00-10:50", InstructorName = "Prof. Emily Dawson", InstructorBio = "Prof. Dawson is a published author and has taught writing at the university level for over 20 years.", IsFeatured = false },
            new() { Id = 9, DepartmentId = 3, CourseCode = "ENG 220", Title = "American Literature", Description = "Survey of American literature from the colonial period to the present, covering major authors and movements.", Credits = 3, Schedule = "TTh 1:00-2:20", InstructorName = "Dr. Michael Torres", InstructorBio = "Dr. Torres specializes in 20th-century American fiction and has published extensively on Faulkner and Morrison.", IsFeatured = true },
            new() { Id = 10, DepartmentId = 3, CourseCode = "ENG 315", Title = "Creative Writing", Description = "Workshop-based course in fiction and poetry writing, with peer review and individual mentoring.", Credits = 3, Schedule = "W 6:00-8:50", InstructorName = "Prof. Emily Dawson", InstructorBio = "Prof. Dawson is a published author and has taught writing at the university level for over 20 years.", IsFeatured = false },

            // Physics
            new() { Id = 11, DepartmentId = 4, CourseCode = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions with hands-on experiments.", Credits = 4, Schedule = "MWF 8:00-8:50", InstructorName = "Dr. Helen Nguyen", InstructorBio = "Dr. Nguyen is an experimental physicist whose research involves particle physics at CERN.", IsFeatured = true },
            new() { Id = 12, DepartmentId = 4, CourseCode = "PHYS 201", Title = "General Physics II", Description = "Electricity, magnetism, optics, and modern physics. Continuation of General Physics I.", Credits = 4, Schedule = "MWF 9:00-9:50", InstructorName = "Dr. Helen Nguyen", InstructorBio = "Dr. Nguyen is an experimental physicist whose research involves particle physics at CERN.", IsFeatured = false },
            new() { Id = 13, DepartmentId = 4, CourseCode = "PHYS 310", Title = "Quantum Mechanics", Description = "Introduction to quantum theory: wave functions, Schrödinger equation, operators, and applications to atoms and molecules.", Credits = 3, Schedule = "TTh 10:00-11:20", InstructorName = "Dr. David Park", InstructorBio = "Dr. Park is a theoretical physicist specializing in quantum computing and quantum information theory.", IsFeatured = false }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
            query = query.Where(c =>
                c.Title.Contains(search, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(search, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(search, StringComparison.OrdinalIgnoreCase));

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public void SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        request.SubmittedAt = DateTime.UtcNow;
        _enrollments.Add(request);
    }
}

