@page "/"
@using UniversityCourseCatalog.Services

@inject CatalogService CatalogService

<PageTitle>University Course Catalog</PageTitle>

<div class="text-center py-5 bg-light rounded mb-4">
    <h1 class="display-4">Welcome to Greenfield University</h1>
    <p class="lead">Explore our diverse academic programs and find the courses that shape your future.</p>
    <a href="courses" class="btn btn-primary btn-lg">Browse All Courses</a>
</div>

<h2 class="mb-3">Featured Courses</h2>
<div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4 mb-5">
    @foreach (var course in featuredCourses)
    {
        var dept = departments.FirstOrDefault(d => d.Id == course.DepartmentId);
        <div class="col">
            <div class="card h-100">
                <div class="card-body">
                    <h5 class="card-title">@course.Title</h5>
                    <h6 class="card-subtitle mb-2 text-muted">@course.CourseCode</h6>
                    <p class="card-text">
                        <span class="badge bg-secondary">@dept?.Name</span>
                        <span class="badge bg-info text-dark">@course.Credits Credits</span>
                    </p>
                </div>
                <div class="card-footer">
                    <a href="courses/@course.Id" class="btn btn-outline-primary btn-sm">View Details</a>
                </div>
            </div>
        </div>
    }
</div>

<h2 class="mb-3">Departments</h2>
<div class="row row-cols-1 row-cols-md-2 g-4">
    @foreach (var dept in departments)
    {
        <div class="col">
            <div class="card h-100">
                <div class="card-body">
                    <h5 class="card-title">@dept.Name</h5>
                    <p class="card-text">@dept.Description</p>
                </div>
                <div class="card-footer">
                    <a href="courses?departmentId=@dept.Id" class="btn btn-outline-primary btn-sm">View Courses</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private List<UniversityCourseCatalog.Models.Course> featuredCourses = new();
    private List<UniversityCourseCatalog.Models.Department> departments = new();

    protected override void OnInitialized()
    {
        featuredCourses = CatalogService.GetFeaturedCourses();
        departments = CatalogService.GetDepartments();
    }
}

@page "/courses"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models

@inject CatalogService CatalogService

<PageTitle>Courses</PageTitle>

@if (department is not null)
{
    <h1>@department.Name Courses</h1>
}
else
{
    <h1>All Courses</h1>
}

<form method="get" action="courses" class="row g-3 mb-4">
    <div class="col-md-6">
        <input type="text" class="form-control" name="search" value="@Search" placeholder="Search courses..." />
    </div>
    <div class="col-md-4">
        <select class="form-select" name="departmentId">
            <option value="">All Departments</option>
            @foreach (var dept in departments)
            {
                if (dept.Id == DepartmentId)
                {
                    <option value="@dept.Id" selected>@dept.Name</option>
                }
                else
                {
                    <option value="@dept.Id">@dept.Name</option>
                }
            }
        </select>
    </div>
    <div class="col-md-2">
        <button type="submit" class="btn btn-primary w-100">Search</button>
    </div>
</form>

@if (courses.Any())
{
    <table class="table table-striped">
        <thead>
            <tr>
                <th>Code</th>
                <th>Title</th>
                <th>Credits</th>
                <th>Department</th>
                <th></th>
            </tr>
        </thead>
        <tbody>
            @foreach (var course in courses)
            {
                var dept = departments.FirstOrDefault(d => d.Id == course.DepartmentId);
                <tr>
                    <td>@course.CourseCode</td>
                    <td>@course.Title</td>
                    <td>@course.Credits</td>
                    <td>@dept?.Name</td>
                    <td><a href="courses/@course.Id" class="btn btn-sm btn-outline-primary">View Details</a></td>
                </tr>
            }
        </tbody>
    </table>
}
else
{
    <div class="alert alert-info">No courses found matching your criteria.</div>
}

@code {
    [SupplyParameterFromQuery]
    public string? Search { get; set; }

    [SupplyParameterFromQuery]
    public int? DepartmentId { get; set; }

    private List<Course> courses = new();
    private List<Department> departments = new();
    private Department? department;

    protected override void OnInitialized()
    {
        departments = CatalogService.GetDepartments();
        courses = CatalogService.GetCourses(Search, DepartmentId);

        if (DepartmentId.HasValue)
            department = CatalogService.GetDepartment(DepartmentId.Value);
    }
}

@page "/courses/{Id:int}"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models

@inject CatalogService CatalogService

@if (course is null)
{
    <PageTitle>Course Not Found</PageTitle>
    <h1>Course Not Found</h1>
    <p>The requested course could not be found.</p>
    <a href="courses" class="btn btn-secondary">Back to Courses</a>
}
else
{
    <PageTitle>@course.Title</PageTitle>

    <nav aria-label="breadcrumb" class="mb-3">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="courses">Courses</a></li>
            <li class="breadcrumb-item active">@course.CourseCode</li>
        </ol>
    </nav>

    <h1>@course.Title</h1>
    <p class="text-muted fs-5">@course.CourseCode &middot; @department?.Name</p>

    <div class="row mb-4">
        <div class="col-md-8">
            <h4>Description</h4>
            <p>@course.Description</p>
        </div>
        <div class="col-md-4">
            <div class="card">
                <div class="card-body">
                    <h5 class="card-title">Course Details</h5>
                    <ul class="list-unstyled">
                        <li><strong>Credits:</strong> @course.Credits</li>
                        <li><strong>Schedule:</strong> @course.Schedule</li>
                        <li><strong>Code:</strong> @course.CourseCode</li>
                    </ul>
                </div>
            </div>
        </div>
    </div>

    <div class="card mb-4">
        <div class="card-body">
            <h4 class="card-title">Instructor</h4>
            <h5>@course.InstructorName</h5>
            <p>@course.InstructorBio</p>
