@page "/enroll"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models

@inject CatalogService CatalogService

<PageTitle>Enroll</PageTitle>

<h1>Course Enrollment</h1>

@if (IsSubmitted)
{
    <div class="alert alert-success">
        <h4>Enrollment Request Submitted!</h4>
        <p><strong>Student Name:</strong> @Model.StudentName</p>
        <p><strong>Student ID:</strong> @Model.StudentId</p>
        <p><strong>Course:</strong> @course?.Title (@course?.CourseCode)</p>
        <p><strong>Submitted At:</strong> @Model.SubmittedAt.ToString("f")</p>
    </div>
    <a href="courses" class="btn btn-primary">Back to Courses</a>
}
else
{
    @if (course is not null)
    {
        <p class="lead">Enrolling in: <strong>@course.Title (@course.CourseCode)</strong></p>
    }
    else
    {
        <div class="alert alert-warning">No course selected. Please select a course from the <a href="courses">course list</a>.</div>
    }

    <EditForm Model="Model" FormName="enrollment" method="post">
        <AntiforgeryToken />
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <input type="hidden" name="Model.CourseId" value="@CourseId" />

        <div class="mb-3">
            <label class="form-label">Student Name</label>
            <InputText class="form-control" @bind-Value="Model.StudentName" />
            <ValidationMessage For="() => Model.StudentName" />
        </div>

        <div class="mb-3">
            <label class="form-label">Student ID</label>
            <InputText class="form-control" @bind-Value="Model.StudentId" />
            <ValidationMessage For="() => Model.StudentId" />
        </div>

        <div class="mb-3">
            <label class="form-label">Course</label>
            <input type="text" class="form-control" value="@(course?.Title ?? "No course selected")" readonly />
        </div>

        <button type="submit" class="btn btn-success">Submit Enrollment</button>
        <a href="courses" class="btn btn-secondary ms-2">Cancel</a>
    </EditForm>
}

@code {
    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    [SupplyParameterFromForm]
    public EnrollmentRequest Model { get; set; } = new();

    private Course? course;
    private bool IsSubmitted;

    protected override void OnInitialized()
    {
        var id = Model.CourseId > 0 ? Model.CourseId : CourseId ?? 0;
        course = CatalogService.GetCourse(id);

        if (Model.CourseId > 0 && !string.IsNullOrWhiteSpace(Model.StudentName) && !string.IsNullOrWhiteSpace(Model.StudentId))
        {
            Model.SubmittedAt = DateTime.UtcNow;
            CatalogService.SubmitEnrollmentRequest(Model);
            IsSubmitted = true;
        }
    }
}

